description:
A fake socket behaves like a real one under load: each `send` accepts only part of what you give it, and each `recv` returns whatever chunk came next. Write the loops from lesson 2.02 against it:

```cpp
class FakeSocket
{
public:
    FakeSocket(std::size_t maxPerSend, std::vector<std::string> incoming);
    int send(const char* data, int length);
    int recv(char* buffer, int size);
    const std::string& wire() const;
    void breakConnection();
};

bool sendAll(FakeSocket& s, const std::string& data);
std::optional<std::string> recvExactly(FakeSocket& s, std::size_t count, std::string& leftover);
std::optional<std::string> recvLine(FakeSocket& s, std::string& leftover);
```

The `FakeSocket` is given (it is in the starter): `send` accepts at most `maxPerSend` bytes and returns how many, or -1 after `breakConnection`; `recv` returns the next incoming chunk (split to fit the buffer), 0 when there are no more chunks, or -1 after `breakConnection`.

- **sendAll** sends every byte, looping; false if `send` fails.
- **recvExactly** returns exactly `count` bytes, first using bytes already in `leftover`, then reading; extra bytes read beyond `count` go back into `leftover`. If the stream ends or fails first, `std::nullopt`.
- **recvLine** returns the next line without its `\n` (and without a `\r` before it), keeping any bytes after it in `leftover`; `std::nullopt` if the stream ends first (a partial line stays in `leftover`).

starter.solution.cpp:
#include <algorithm>
#include <cstring>
#include <deque>
#include <optional>
#include <string>
#include <vector>

class FakeSocket
{
public:
    FakeSocket(std::size_t maxPerSend, std::vector<std::string> incoming) : maxPerSend{ maxPerSend }, chunks{ incoming.begin(), incoming.end() } {}
    int send(const char* data, int length)
    {
        if (broken) return -1;
        const int n{ static_cast<int>(std::min<std::size_t>(maxPerSend, static_cast<std::size_t>(length))) };
        sent.append(data, static_cast<std::size_t>(n));
        return n;
    }
    int recv(char* buffer, int size)
    {
        if (broken) return -1;
        if (chunks.empty()) return 0;
        std::string& c{ chunks.front() };
        const std::size_t n{ std::min<std::size_t>(c.size(), static_cast<std::size_t>(size)) };
        std::memcpy(buffer, c.data(), n);
        c.erase(0, n);
        if (c.empty()) chunks.pop_front();
        return static_cast<int>(n);
    }
    const std::string& wire() const { return sent; }
    void breakConnection() { broken = true; }

private:
    std::size_t maxPerSend;
    std::deque<std::string> chunks;
    std::string sent;
    bool broken{ false };
};

bool sendAll(FakeSocket& s, const std::string& data) { return s.send(data.data(), static_cast<int>(data.size())) >= 0; }
std::optional<std::string> recvExactly(FakeSocket& s, std::size_t count, std::string& leftover) { return std::nullopt; }
std::optional<std::string> recvLine(FakeSocket& s, std::string& leftover) { return std::nullopt; }

