#include <algorithm>
#include <cstring>
#include <deque>
#include <optional>
#include <string>
#include <vector>

class FakeSocket
{
public:
    FakeSocket(std::size_t maxPerSend, std::vector<std::string> incoming) : maxPerSend{ maxPerSend }, chunks{ incoming.begin(), incoming.end() } {}
    int send(const char* data, int length)
    {
        if (broken) return -1;
        const int n{ static_cast<int>(std::min<std::size_t>(maxPerSend, static_cast<std::size_t>(length))) };
        sent.append(data, static_cast<std::size_t>(n));
        return n;
    }
    int recv(char* buffer, int size)
    {
        if (broken) return -1;
        if (chunks.empty()) return 0;
        std::string& c{ chunks.front() };
        const std::size_t n{ std::min<std::size_t>(c.size(), static_cast<std::size_t>(size)) };
        std::memcpy(buffer, c.data(), n);
        c.erase(0, n);
        if (c.empty()) chunks.pop_front();
        return static_cast<int>(n);
    }
    const std::string& wire() const { return sent; }
    void breakConnection() { broken = true; }

private:
    std::size_t maxPerSend;
    std::deque<std::string> chunks;
    std::string sent;
    bool broken{ false };
};

bool sendAll(FakeSocket& s, const std::string& data)
{
    std::size_t at{ 0 };
    while (at < data.size())
    {
        const int n{ s.send(data.data() + at, static_cast<int>(data.size() - at)) };
        if (n < 0) return false;
        at += static_cast<std::size_t>(n);
    }
    return true;
}

static bool readMore(FakeSocket& s, std::string& leftover)
{
    char chunk[512];
    const int got{ s.recv(chunk, sizeof(chunk)) };
    if (got <= 0) return false;
    leftover.append(chunk, static_cast<std::size_t>(got));
    return true;
}

std::optional<std::string> recvExactly(FakeSocket& s, std::size_t count, std::string& leftover)
{
    while (leftover.size() < count)
        if (!readMore(s, leftover)) return std::nullopt;
    std::string out{ leftover.substr(0, count) };
    leftover.erase(0, count);
    return out;
}

std::optional<std::string> recvLine(FakeSocket& s, std::string& leftover)
{
    std::size_t end{ leftover.find('\n') };
    while (end == std::string::npos)
    {
        if (!readMore(s, leftover)) return std::nullopt;
        end = leftover.find('\n');
    }
    std::string line{ leftover.substr(0, end) };
    leftover.erase(0, end + 1);
    if (!line.empty() && line.back() == '\r') line.pop_back();
    return line;
}

unitTests:
TEST("sending everything, a few bytes at a time") {
    FakeSocket s{ 3, {} };
    CHECK(sendAll(s, "hello, network"));
    CHECK_EQ(s.wire(), std::string("hello, network"));
    FakeSocket broken{ 3, {} };
    broken.breakConnection();
    CHECK(!sendAll(broken, "x"));
    CHECK(sendAll(broken, ""));
}
TEST("exact reads across chunks") {
    FakeSocket s{ 100, { "he", "llo wor", "ld!!" } };
    std::string leftover;
    CHECK_EQ(recvExactly(s, 5, leftover).value_or("?"), std::string("hello"));
    CHECK_EQ(leftover, std::string(" wor"));
    CHECK_EQ(recvExactly(s, 7, leftover).value_or("?"), std::string(" world!"));
    CHECK_EQ(recvExactly(s, 1, leftover).value_or("?"), std::string("!"));
    CHECK(!recvExactly(s, 1, leftover).has_value());
}
TEST("lines") {
    FakeSocket s{ 100, { "GET /a\r\nHost: x", "\r\n\r\npartial" } };
    std::string leftover;
    CHECK_EQ(recvLine(s, leftover).value_or("?"), std::string("GET /a"));
    CHECK_EQ(recvLine(s, leftover).value_or("?"), std::string("Host: x"));
    CHECK_EQ(recvLine(s, leftover).value_or("?"), std::string(""));
    CHECK(!recvLine(s, leftover).has_value());
    CHECK_EQ(leftover, std::string("partial"));
}
TEST("a broken connection mid-read") {
    FakeSocket s{ 100, { "abc" } };
    std::string leftover;
    s.breakConnection();
    CHECK(!recvExactly(s, 2, leftover).has_value());
}

